/bin/bash -lc "python - <<'PY'
import json, urllib.request
for p in range(1,8):
 u=f'https://quay.io/api/v1/repository/biocontainers/scanpy/tag/?onlyActiveTags=true&limit=100&page={p}'
 with urllib.request.urlopen(u) as f: d=json.load(f)
 tags=d.get('tags',[])
 print('PAGE',p,'N',len(tags),'LAST',tags[-1]['name'] if tags else None)
 for t in tags:
  if t['name'].startswith(('1.9','1.10','1.11')): print(t['name'],t.get('manifest_digest',''))
PY"

/bin/bash -lc "python - <<'PY'
import json, urllib.request
for p in range(1,8):
 u=f'https://quay.io/api/v1/repository/biocontainers/scanpy/tag/?onlyActiveTags=true&limit=100&page={p}'
 with urllib.request.urlopen(u) as f: d=json.load(f)
 tags=d.get('tags',[])
 print('PAGE',p,'N',len(tags),'LAST',tags[-1]['name'] if tags else None)
 for t in tags:
  if t['name'].startswith(('1.9','1.10','1.11')): print(t['name'],t.get('manifest_digest',''))
PY"

